/**
 * NeuroshillingRoleInput
 *
 * One role as the form declares it.
 *
 * ``role_id`` is how a step says WHICH role speaks, and it is matched against the
 * campaign's stored roles: a value that is already one of them updates that row
 * in place — which is what keeps the account roster's ``role_id`` pointing
 * somewhere after a save — and anything else (including ``None``) mints a new
 * role. So a client may invent keys for roles that do not exist yet, and the
 * server rewires the steps to the real ids it mints.
 */
export type NeuroshillingRoleInput = {
  /**
   * Role Id
   */
  role_id?: string | null;
  /**
   * Name
   */
  name: string;
  /**
   * Description
   */
  description?: string;
};

/**
 * NeuroshillingRunStatus
 *
 * What the launch card shows: where the run is and how far it has got.
 *
 * ``sent`` counts delivered MESSAGE steps of the current run and ``total`` is
 * targets x message steps. Reactions are journalled but counted in neither, because
 * a skipped reaction is not lost progress.
 *
 * ``halted_accounts`` are the accounts Telegram has taken out of the run — a flood
 * wait, a peer flood, or the 500-chat ceiling. They are read back from the durable
 * presence rows rather than from a run-local set, so a restart does not forget them.
 *
 * ``substitutions`` is how many accounts a reserve one has taken over from. It is
 * here rather than derived on the client because the board's roster carries
 * ``state`` but not ``replaced_by_account_id``, and a ban with an empty reserve pool
 * writes the first without the second.
 *
 * ``listening`` says the run is reading its target chats as well as writing to
 * them. Not derivable on the client from the campaign row alone: the three switches
 * that turn it on are stored, but whether a run is actually in flight is not.
 *
 * ``total`` is zero in ``revive`` mode and that is a value rather than a gap: a
 * revive campaign loops until it is stopped, so there is no denominator to divide
 * by and the card shows a counter instead of a bar.
 */
export type NeuroshillingRunStatus = {
  /**
   * Status
   */
  status?: 'idle' | 'running' | 'stopping' | 'done' | 'failed';
  /**
   * Run Id
   */
  run_id?: string | null;
  /**
   * Sent
   */
  sent?: number;
  /**
   * Total
   */
  total?: number;
  /**
   * Substitutions
   */
  substitutions?: number;
  /**
   * Listening
   */
  listening?: boolean;
  /**
   * Chat Messages Seen
   */
  chat_messages_seen?: number;
  /**
   * Human Replies Sent
   */
  human_replies_sent?: number;
  /**
   * Last Error Type
   */
  last_error_type?: string | null;
  /**
   * Halted Accounts
   */
  halted_accounts?: Array<string>;
};

